export default scene({ mode: "2d", end: "advance", background: "BLACK" }, s => {
  // ---------- control ----------
  const deg = s.slider("rotation_angle", {
    label: "Rotation angle", default: 90, min: 0, max: 180, step: 15,
    position: [0.05, 0.80], width: 220,
  });
  const th = deg * Math.PI / 180;
  const c = Math.cos(th), sn = Math.sin(th);

  // ---------- fixed layout ----------
  const OX = -2.35;          // origin of the plane (centre of the geometry area)
  const U = 1.3;             // world length of one grid unit
  const PX = 4.74;           // centre of the text panel
  const N = 10;              // moving grid: lines -N..N
  const G = 5;               // ghost grid: lines -G..G

  // ---------- linear algebra helpers (plane coordinates) ----------
  const mul = (A, B) => [
    [A[0][0] * B[0][0] + A[0][1] * B[1][0], A[0][0] * B[0][1] + A[0][1] * B[1][1]],
    [A[1][0] * B[0][0] + A[1][1] * B[1][0], A[1][0] * B[0][1] + A[1][1] * B[1][1]],
  ];
  const ap = (A, p) => [A[0][0] * p[0] + A[0][1] * p[1], A[1][0] * p[0] + A[1][1] * p[1]];
  const W = p => [U * p[0], U * p[1]];
  const I2 = [[1, 0], [0, 1]];
  const R = [[c, -sn], [sn, c]];
  const Rinv = [[c, sn], [-sn, c]];
  const S = [[1, 1], [0, 1]];
  const T = mul(S, R);                 // first R, then S
  const M = mul(Rinv, T);              // shear expressed inside the rotated group

  // ---------- ghost of the starting grid (muted, behind everything) ----------
  const ghostLines = [];
  for (let i = -G; i <= G; i++) {
    ghostLines.push(s.line("ghost-v-" + i, { points: [W([i, -8]), W([i, 8])], stroke: "GREY_D", strokeWidth: 0.02 }));
    ghostLines.push(s.line("ghost-h-" + i, { points: [W([-8, i]), W([8, i])], stroke: "GREY_D", strokeWidth: 0.02 }));
  }
  const ghost = s.group("ghost-grid", ghostLines);
  s.play(ghost.moveTo([OX, 0, -0.2]), { duration: 0 });

  // ---------- the moving plane ----------
  const lines = [];
  for (let i = -N; i <= N; i++) {
    const axis = i === 0;
    const style = { stroke: axis ? "GREY_A" : "GREY_C", strokeWidth: axis ? 0.03 : 0.02 };
    const v = { a: [i, -N], b: [i, N] };
    const h = { a: [-N, i], b: [N, i] };
    v.el = s.line("grid-v-" + i, { points: [W(v.a), W(v.b)], ...style });
    h.el = s.line("grid-h-" + i, { points: [W(h.a), W(h.b)], ...style });
    lines.push(v, h);
  }
  const E1 = [1, 0], E2 = [0, 1];
  const L1 = [0.62, -0.4], L2 = [-0.4, 0.62];   // label spots, inside a grid cell beside each tip
  const e1 = s.arrow("e1", { points: [[0, 0], W(E1)], stroke: "GREEN", strokeWidth: 0.09, position: [0, 0, 0.1] });
  const e2 = s.arrow("e2", { points: [[0, 0], W(E2)], stroke: "RED", strokeWidth: 0.09, position: [0, 0, 0.1] });
  const lab1 = s.latex("e1-label", { tex: "e_1", fontSize: 0.5, fill: "GREEN", position: [U * L1[0], U * L1[1], 0.15] });
  const lab2 = s.latex("e2-label", { tex: "e_2", fontSize: 0.5, fill: "RED", position: [U * L2[0], U * L2[1], 0.15] });
  const plane = s.group("grid", lines.map(l => l.el).concat([e1, e2, lab1, lab2]));
  s.play(plane.moveTo([OX, 0, 0]), { duration: 0 });

  const lineTo = (A, l) => l.el.morphTo({ kind: "line", points: [W(ap(A, l.a)), W(ap(A, l.b))], closed: false });
  const arrowTo = (A, el, p) => el.morphTo({ kind: "arrow", points: [[0, 0], W(ap(A, p))], closed: false });
  const labelTo = (A, el, p) => { const q = ap(A, p); return el.moveTo([U * q[0], U * q[1], 0.15]); };
  const planeTo = A => lines.map(l => lineTo(A, l)).concat([
    arrowTo(A, e1, E1), arrowTo(A, e2, E2), labelTo(A, lab1, L1), labelTo(A, lab2, L2),
  ]);

  // ---------- panel (masks the plane on the right third) ----------
  const mask = s.rectangle("panel-mask", { width: 40, height: 60, position: [22.4, 0, 0.4], fill: "BLACK", stroke: "none" });
  const panel = s.rectangle("panel", { width: 4.3, height: 7.2, position: [PX, 0, 0.5], fill: "GREY_E", stroke: "GREY_C", strokeWidth: 0.02 });

  // ---------- panel formulas ----------
  const fmt = v => {
    const r = Math.round(v * 100) / 100;
    if (r === 0) return "0";
    if (Number.isInteger(r)) return String(r);
    return String(parseFloat(r.toFixed(2)));
  };
  const em = str => {
    let w = 0;
    for (const ch of str) w += ch === "-" ? 0.78 : ch === "." ? 0.28 : 0.5;
    return w;
  };
  const r11 = fmt(c), r12 = fmt(-sn), r21 = fmt(sn), r22 = fmt(c);
  const wR = 2.16 + Math.max(em(r11), em(r21)) + Math.max(em(r12), em(r22));
  const wS = 3.16;
  const gap = 0.45;
  const F = Math.min(0.42, (3.7 - gap) / (wR + wS));
  const total = (wR + wS) * F + gap;
  const left = PX - total / 2;
  const xR = left + wR * F / 2;
  const xS = left + wR * F + gap + wS * F / 2;
  const matTex = (name, a, b, cc, d) =>
    String.raw`\begin{array}{c}\animpart{name}{` + name + String.raw`}\\[0.25em]\begin{bmatrix}\animpart{a11}{` + a +
    String.raw`}&\animpart{a12}{` + b + String.raw`}\\ \animpart{a21}{` + cc + String.raw`}&\animpart{a22}{` + d +
    String.raw`}\end{bmatrix}\end{array}`;
  const matR = s.latex("matrix-R", { tex: matTex("R", r11, r12, r21, r22), fontSize: F, fill: "BLUE", position: [xR, 2.45, 0.6], opacity: 0 });
  const matS = s.latex("matrix-S", { tex: matTex("S", "1", "1", "0", "1"), fontSize: F, fill: "GOLD", position: [xS, 2.45, 0.6], opacity: 0 });

  const frame = s.rectangle("product-frame", { width: 3.4, height: 2.3, position: [PX, -0.4, 0.55], fill: "none", stroke: "TEAL", strokeWidth: 0.03, opacity: 0 });
  const bracket = s.latex("product-bracket", {
    tex: String.raw`\begin{bmatrix}\phantom{-1}&\phantom{-1}\\ \phantom{-1}&\phantom{-1}\end{bmatrix}`,
    fontSize: 0.6, fill: "WHITE", position: [PX, -0.4, 0.6], opacity: 0,
  });
  const question = s.latex("product-question", { tex: "?", fontSize: 0.7, fill: "WHITE", position: [PX, -0.4, 0.62], opacity: 0 });

  // ---------- timeline (50 s) ----------
  s.wait(2.5);

  // 1. the rotation R: interpolated by angle; labels stay upright
  s.play([plane.rotateTo(th), lab1.rotateTo(-th), lab2.rotateTo(-th), matR.fadeIn()], { duration: 5.5, ease: "smooth" });
  s.wait(2);

  // 2. the shear S: one parameter, (1-t) I + t S applied after the rotation
  s.play(planeTo(M).concat([matS.fadeIn()]), { duration: 5.5, ease: "smooth" });
  s.wait(1.5);

  // the origin has not moved
  const dot = s.circle("origin-dot", { radius: 0.1, position: [OX, 0, 0.2], fill: "WHITE", stroke: "none", opacity: 0 });
  s.play(dot.fadeIn(), { duration: 1, ease: "smooth" });
  s.wait(3);
  s.play(dot.fadeOut(), { duration: 1, ease: "smooth" });
  s.remove(dot);
  s.wait(0.5);

  // 3. ease calmly back onto the ghost
  s.play(planeTo(I2).concat([plane.rotateTo(0), lab1.rotateTo(0), lab2.rotateTo(0)]), { duration: 5, ease: "smooth" });
  s.wait(2);

  // 4. the same result as ONE motion: (1-t) I + t (S R), no stop in the middle
  s.play(planeTo(T), { duration: 8, ease: "smooth" });
  s.wait(3.5);

  // 5. one linear map, one matrix: which one?
  s.play([frame.fadeIn(), bracket.fadeIn()], { duration: 2, ease: "smooth" });
  s.wait(0.5);
  s.play(question.fadeIn(), { duration: 1.5, ease: "smooth" });
  s.wait(5);

  // ---------- handoff ----------
  s.keep(ghost);
  s.keep(plane);
  s.keep(mask);
  s.keep(panel);
  s.keep(matR);
  s.keep(matS);
  s.keep(frame);
  s.keep(bracket);
  s.keep(question);
});

export default scene({ mode: "2d", end: "advance", background: "BLACK" }, s => {
  // ---------- fixed layout (identical to the previous scene) ----------
  const OX = -2.35;          // origin of the plane
  const U = 1.3;             // world length of one grid unit
  const PX = 4.74;           // centre of the text panel
  const N = 10;              // moving grid: lines -N..N

  // ---------- the running example: quarter-turn R, then shear S ----------
  const th = Math.PI / 2;
  const c = Math.cos(th), sn = Math.sin(th);
  const mul = (A, B) => [
    [A[0][0] * B[0][0] + A[0][1] * B[1][0], A[0][0] * B[0][1] + A[0][1] * B[1][1]],
    [A[1][0] * B[0][0] + A[1][1] * B[1][0], A[1][0] * B[0][1] + A[1][1] * B[1][1]],
  ];
  const ap = (A, p) => [A[0][0] * p[0] + A[0][1] * p[1], A[1][0] * p[0] + A[1][1] * p[1]];
  const W = p => [U * p[0], U * p[1]];
  const I2 = [[1, 0], [0, 1]];
  const R = [[c, -sn], [sn, c]];
  const Rinv = [[c, sn], [-sn, c]];
  const S = [[1, 1], [0, 1]];
  const T = mul(S, R);                 // first R, then S
  const M = mul(Rinv, T);              // the shear, expressed inside the rotated group

  // ---------- objects inherited from the previous scene ----------
  const ghost = s.previous.get("ghost-grid");
  const plane = s.previous.get("grid");
  const mask = s.previous.get("panel-mask");
  const panel = s.previous.get("panel");
  const matR = s.previous.get("matrix-R");
  const matS = s.previous.get("matrix-S");
  const frame = s.previous.get("product-frame");
  const bracket = s.previous.get("product-bracket");
  const question = s.previous.get("product-question");
  const e1 = s.previous.get("e1");
  const e2 = s.previous.get("e2");
  const lab1 = s.previous.get("e1-label");
  const lab2 = s.previous.get("e2-label");

  const lines = [];
  for (let i = -N; i <= N; i++) {
    lines.push({ a: [i, -N], b: [i, N], el: s.previous.get("grid-v-" + i) });
    lines.push({ a: [-N, i], b: [N, i], el: s.previous.get("grid-h-" + i) });
  }
  const E1 = [1, 0], E2 = [0, 1];
  const L1 = [0.62, -0.4], L2 = [-0.4, 0.62];     // home spots of the labels
  const Q1 = [1.42, 1.08];                        // e1 label beside the final tip (1,1), clear of the drop lines
  const Q2 = ap(R, L2);                           // e2 label stays where the rotation puts it

  const lineTo = (A, l) => l.el.morphTo({ kind: "line", points: [W(ap(A, l.a)), W(ap(A, l.b))], closed: false });
  const arrowTo = (A, el, p) => el.morphTo({ kind: "arrow", points: [[0, 0], W(ap(A, p))], closed: false });
  const labelAt = (el, q) => el.moveTo([U * q[0], U * q[1], 0.15]);
  const gridTo = A => lines.map(l => lineTo(A, l)).concat([arrowTo(A, e1, E1), arrowTo(A, e2, E2)]);

  // ---------- helpers created for this scene ----------
  // the line the shear leaves in place: the horizontal axis (gold = shear)
  const glow = s.line("shear-fixed-axis", {
    points: [[OX - 6, 0], [OX + 6, 0]],
    stroke: { color: "GOLD", opacity: 0.45 }, strokeWidth: 0.14,
    position: [0, 0, 0.05], opacity: 0,
  });

  const tip1 = [OX + U, U];
  const dropV = s.line("e1-drop-vertical", {
    points: [tip1, [tip1[0], tip1[1] - 0.02]],
    stroke: "GREY_B", strokeWidth: 0.05, position: [0, 0, 0.08], opacity: 0,
  });
  const dropH = s.line("e1-drop-horizontal", {
    points: [tip1, [tip1[0] - 0.02, tip1[1]]],
    stroke: "GREY_B", strokeWidth: 0.05, position: [0, 0, 0.08], opacity: 0,
  });
  const ring = s.circle("e2-axis-marker", {
    radius: 0.22, position: [OX - U, 0, 0.08],
    fill: "none", stroke: "GREY_B", strokeWidth: 0.05, opacity: 0,
  });

  // the two columns: same matrix layout as the bracket, so they drop exactly into its cells
  const FS = 0.6;
  const COLX = 1.139 * FS;        // distance of a column centre from the bracket centre
  const STAGE_Y = -2.6;
  const col1 = s.latex("product-col1", {
    tex: String.raw`\begin{matrix}\animpart{top}{1}&\phantom{-1}\\ \animpart{bottom}{1}&\phantom{-1}\end{matrix}`,
    fontSize: FS, fill: "GREEN", position: [PX + COLX, STAGE_Y, 0.62], opacity: 0,
  });
  const col2 = s.latex("product-col2", {
    tex: String.raw`\begin{matrix}\phantom{-1}&\animpart{top}{-1}\\ \phantom{-1}&\animpart{bottom}{0}\end{matrix}`,
    fontSize: FS, fill: "RED", position: [PX - COLX, STAGE_Y, 0.62], opacity: 0,
  });

  // ---------- timeline (45 s) ----------
  s.wait(2);

  // 1. ease back onto the ghost grid: e1 and e2 are home again
  s.play(gridTo(I2).concat([
    plane.rotateTo(0), lab1.rotateTo(0), lab2.rotateTo(0),
    labelAt(lab1, L1), labelAt(lab2, L2),
  ]), { duration: 4, ease: "smooth" });
  s.wait(1);

  // 2. the rotation, by angle: e1 ends pointing up, e2 ends on the horizontal axis
  s.play([plane.rotateTo(th), lab1.rotateTo(-th), lab2.rotateTo(-th)], { duration: 5, ease: "smooth" });
  s.wait(2.5);

  // 3. the shear: e1's tip slides sideways, e2 lies on the fixed axis and stays put
  s.play(gridTo(M).concat([
    labelAt(lab1, ap(Rinv, Q1)),
    glow.fadeIn(),
  ]), { duration: 5, ease: "smooth" });
  s.wait(1.5);
  s.play(glow.fadeOut(), { duration: 1, ease: "smooth" });
  s.remove(glow);

  // same picture, re-expressed without the group rotation (no visible change)
  s.play(gridTo(T).concat([
    plane.rotateTo(0), lab1.rotateTo(0), lab2.rotateTo(0),
    labelAt(lab1, Q1), labelAt(lab2, Q2),
  ]), { duration: 0 });
  s.wait(1);

  // 4. read off e1: drop lines to the axes of the ghost grid, coordinates into column 1
  s.play([
    dropV.fadeIn(), dropH.fadeIn(),
    dropV.morphTo({ kind: "line", points: [tip1, [tip1[0], 0]], closed: false }),
    dropH.morphTo({ kind: "line", points: [tip1, [OX, tip1[1]]], closed: false }),
  ], { duration: 1.5, ease: "smooth" });
  s.wait(0.5);
  s.play(col1.fadeIn(), { duration: 1.2, ease: "smooth" });
  s.wait(1);
  s.play([col1.moveTo([PX, -0.4, 0.62]), question.fadeOut()], { duration: 2, ease: "smooth" });
  s.remove(question);
  s.wait(1);
  s.play([dropV.fadeOut(), dropH.fadeOut()], { duration: 1, ease: "smooth" });
  s.remove(dropV);
  s.remove(dropH);
  s.wait(0.8);

  // 5. read off e2: its tip sits on the horizontal axis, coordinates into column 2
  s.play(ring.fadeIn(), { duration: 1.2, ease: "smooth" });
  s.wait(0.5);
  s.play(col2.fadeIn(), { duration: 1.2, ease: "smooth" });
  s.wait(1);
  s.play(col2.moveTo([PX, -0.4, 0.62]), { duration: 2, ease: "smooth" });
  s.wait(1);
  s.play(ring.fadeOut(), { duration: 1, ease: "smooth" });
  s.remove(ring);

  // hold the finished matrix: green first column, red second column
  s.wait(5.1);

  // ---------- handoff ----------
  s.keep(ghost);
  s.keep(plane);
  s.keep(mask);
  s.keep(panel);
  s.keep(matR);
  s.keep(matS);
  s.keep(frame);
  s.keep(bracket);
  s.keep(col1);
  s.keep(col2);
});

export default scene({ mode: "2d", end: "advance", background: "BLACK" }, s => {
  // ---------- control ----------
  const k = s.slider("shear_amount", {
    label: "Shear amount", default: 1, min: 0, max: 2, step: 0.5,
    position: [0.05, 0.80], width: 220,
  });

  // ---------- fixed layout (identical to the previous scenes) ----------
  const OX = -2.35;          // origin of the plane
  const U = 1.3;             // world length of one grid unit
  const PX = 4.74;           // centre of the text panel
  const N = 10;              // moving grid: lines -N..N

  // ---------- the running example: quarter-turn R, then shear S (amount k) ----------
  const mul = (A, B) => [
    [A[0][0] * B[0][0] + A[0][1] * B[1][0], A[0][0] * B[0][1] + A[0][1] * B[1][1]],
    [A[1][0] * B[0][0] + A[1][1] * B[1][0], A[1][0] * B[0][1] + A[1][1] * B[1][1]],
  ];
  const ap = (A, p) => [A[0][0] * p[0] + A[0][1] * p[1], A[1][0] * p[0] + A[1][1] * p[1]];
  const W = p => [U * p[0], U * p[1]];
  const R = [[0, -1], [1, 0]];
  const S = [[1, k], [0, 1]];
  const T = mul(S, R);                 // first R, then S

  const fmt = v => {
    const r = Math.round(v * 100) / 100;
    if (r === 0) return "0";
    if (Number.isInteger(r)) return String(r);
    return String(parseFloat(r.toFixed(2)));
  };
  const em = str => {
    let w = 0;
    for (const ch of str) w += ch === "-" ? 0.78 : ch === "." ? 0.28 : 0.5;
    return w;
  };
  const kTex = fmt(k);

  // ---------- objects inherited from the previous scene ----------
  const ghost = s.previous.get("ghost-grid");
  const plane = s.previous.get("grid");
  const mask = s.previous.get("panel-mask");
  const panel = s.previous.get("panel");
  const matR = s.previous.get("matrix-R");
  const matS = s.previous.get("matrix-S");
  const frame = s.previous.get("product-frame");
  const bracket = s.previous.get("product-bracket");
  const col1 = s.previous.get("product-col1");
  const col2 = s.previous.get("product-col2");
  const e1 = s.previous.get("e1");
  const e2 = s.previous.get("e2");
  const lab1 = s.previous.get("e1-label");

  const lines = [];
  for (let i = -N; i <= N; i++) {
    lines.push({ a: [i, -N], b: [i, N], el: s.previous.get("grid-v-" + i) });
    lines.push({ a: [-N, i], b: [N, i], el: s.previous.get("grid-h-" + i) });
  }
  const E1 = [1, 0], E2 = [0, 1];
  const QH = [0.42, 1.08];              // e1 label beside the halfway tip (0,1)
  const QF = [k + 0.42, 1.08];          // e1 label beside the final tip (k,1)

  const lineTo = (A, l) => l.el.morphTo({ kind: "line", points: [W(ap(A, l.a)), W(ap(A, l.b))], closed: false });
  const arrowTo = (A, el, p) => el.morphTo({ kind: "arrow", points: [[0, 0], W(ap(A, p))], closed: false });
  const labelAt = (el, q) => el.moveTo([U * q[0], U * q[1], 0.15]);
  const gridTo = A => lines.map(l => lineTo(A, l)).concat([arrowTo(A, e1, E1), arrowTo(A, e2, E2)]);

  // ---------- panel formulas ----------
  const F = 0.42;                       // font size of R and S (as laid out in scene 1)
  const XR = 3.8514, YM = 2.45;         // centre of the R matrix
  const FS = 0.6;                       // font size of the product matrix
  const COLX = 1.139 * FS;              // distance of a product column from the bracket centre
  const YP = -0.4;                      // centre of the product matrix

  const matTex = (name, a, b, c, d) =>
    String.raw`\begin{array}{c}\animpart{name}{` + name + String.raw`}\\[0.25em]\begin{bmatrix}\animpart{a11}{` + a +
    String.raw`}&\animpart{a12}{` + b + String.raw`}\\ \animpart{a21}{` + c + String.raw`}&\animpart{a22}{` + d +
    String.raw`}\end{bmatrix}\end{array}`;

  // R keeps its blue letter and frame; its entries are handed over to two coloured columns
  const frameTexR = String.raw`\begin{array}{c}\animpart{name}{R}\\[0.25em]\begin{bmatrix}\phantom{0}&\phantom{-1}\\ \phantom{1}&\phantom{0}\end{bmatrix}\end{array}`;
  const VP = String.raw`\vphantom{\begin{matrix}0&-1\\ 1&0\end{matrix}}`;
  const PL = String.raw`\phantom{\left[` + VP + String.raw`\right.}`;
  const PR = String.raw`\phantom{\left.` + VP + String.raw`\right]}`;
  const rColTex = body => String.raw`\begin{array}{c}\phantom{R}\\[0.25em]` + PL + body + PR + String.raw`\end{array}`;
  const rc1 = s.latex("matrix-R-col1", {
    tex: rColTex(String.raw`\begin{matrix}\animpart{top}{0}&\phantom{-1}\\ \animpart{bottom}{1}&\phantom{0}\end{matrix}`),
    fontSize: F, fill: "GREEN", position: [XR, YM, 0.62], opacity: 0,
  });
  const rc2 = s.latex("matrix-R-col2", {
    tex: rColTex(String.raw`\begin{matrix}\phantom{0}&\animpart{top}{-1}\\ \phantom{1}&\animpart{bottom}{0}\end{matrix}`),
    fontSize: F, fill: "RED", position: [XR, YM, 0.62], opacity: 0,
  });

  // one line of working:  S [column of R] = [column of the product]
  const FL = 0.5;
  const YL = -2.6;
  const mkLine = (n, color, inTop, inBot, outTop, outBot) => {
    const wS = 0.65, g1 = 0.12, g2 = 0.3, wEq = 0.78;
    const wIn = Math.max(em(inTop), em(inBot)) + 1.16;
    const wOut = Math.max(em(outTop), em(outBot)) + 1.16;
    const total = (wS + g1 + wIn + g2 + wEq + g2 + wOut) * FL;
    let x = PX - total / 2;
    const xS = x + wS * FL / 2; x += (wS + g1) * FL;
    const xIn = x + wIn * FL / 2; x += (wIn + g2) * FL;
    const xEq = x + wEq * FL / 2; x += (wEq + g2) * FL;
    const xOut = x + wOut * FL / 2;
    const id = "working-" + n;
    return {
      letter: s.latex(id + "-S", { tex: "S", fontSize: FL, fill: "GOLD", position: [xS, YL, 0.62], opacity: 0 }),
      input: s.latex(id + "-column-of-R", {
        tex: String.raw`\begin{bmatrix}` + inTop + String.raw`\\ ` + inBot + String.raw`\end{bmatrix}`,
        fontSize: FL, fill: color, position: [xIn, YL, 0.62], opacity: 0,
      }),
      eq: s.latex(id + "-equals", { tex: "=", fontSize: FL, fill: "WHITE", position: [xEq, YL, 0.62], opacity: 0 }),
      outBr: s.latex(id + "-result-bracket", {
        tex: String.raw`\begin{bmatrix}\phantom{` + outTop + String.raw`}\\ \phantom{` + outBot + String.raw`}\end{bmatrix}`,
        fontSize: FL, fill: color, position: [xOut, YL, 0.62], opacity: 0,
      }),
      // result numbers: same size as the product entries once they land (scale 1)
      out: s.latex(id + "-result", {
        tex: String.raw`\begin{matrix}\animpart{top}{` + outTop + String.raw`}\\ \animpart{bottom}{` + outBot + String.raw`}\end{matrix}`,
        fontSize: FS, scale: FL / FS, fill: color, position: [xOut, YL, 0.66], opacity: 0,
      }),
    };
  };
  const line1 = mkLine(1, "GREEN", "0", "1", kTex, "1");
  const line2 = mkLine(2, "RED", "-1", "0", "-1", "0");

  const runLine = (ln, arrow, targetX) => {
    // S meets a column of R; the arrow that column describes glows
    s.play([ln.letter.fadeIn(), ln.input.fadeIn(), arrow.animate({ strokeWidth: 0.15 })], { duration: 1.2, ease: "smooth" });
    s.wait(0.6);
    s.play([ln.eq.fadeIn(), ln.outBr.fadeIn(), ln.out.fadeIn()], { duration: 1.2, ease: "smooth" });
    s.wait(2);
    // the result slides onto the matching column of the product and agrees with it
    s.play([ln.out.moveTo([targetX, YP, 0.66]), ln.out.scaleTo(1), ln.outBr.fadeOut()], { duration: 1.8, ease: "smooth" });
    s.play(ln.out.scaleTo(1.25), { duration: 0.5, ease: "smooth" });
    s.play(ln.out.scaleTo(1), { duration: 0.5, ease: "smooth" });
    s.play([
      ln.letter.fadeOut(), ln.input.fadeOut(), ln.eq.fadeOut(), ln.out.fadeOut(),
      arrow.animate({ strokeWidth: 0.09 }),
    ], { duration: 1, ease: "smooth" });
    s.remove(ln.letter);
    s.remove(ln.input);
    s.remove(ln.eq);
    s.remove(ln.outBr);
    s.remove(ln.out);
  };

  // ---------- timeline (45 s) ----------
  // bring the inherited picture in line with the chosen shear amount (no change at the default)
  if (k !== 1) {
    s.play(gridTo(T).concat([
      labelAt(lab1, QF),
      matS.morphTo({ kind: "latex", tex: matTex("S", "1", kTex, "0", "1"), fontSize: F },
        { map: { name: "name", a11: "a11", a12: "a12", a21: "a21", a22: "a22" } }),
      col1.morphTo({
        kind: "latex",
        tex: String.raw`\begin{matrix}\animpart{top}{` + kTex + String.raw`}&\phantom{-1}\\ \animpart{bottom}{1}&\phantom{-1}\end{matrix}`,
        fontSize: FS,
      }, { map: { top: "top", bottom: "bottom" } }),
    ]), { duration: 0 });
  }
  s.wait(1.5);

  // 1. undo the shear: the plane rests in the halfway position, rotated only
  s.play(gridTo(R).concat([labelAt(lab1, QH)]), { duration: 4, ease: "smooth" });
  s.wait(1.2);

  // 2. the columns of R take the colours of the arrows
  s.play([
    matR.morphTo({ kind: "latex", tex: frameTexR, fontSize: F }, { map: { name: "name" } }),
    rc1.fadeIn(), rc2.fadeIn(),
  ], { duration: 1.8, ease: "smooth" });
  s.wait(0.7);

  // 3. each column pulses with the arrow it describes
  s.play([rc1.scaleTo(1.12), e1.animate({ strokeWidth: 0.15 })], { duration: 0.7, ease: "smooth" });
  s.play([rc1.scaleTo(1), e1.animate({ strokeWidth: 0.09 })], { duration: 0.7, ease: "smooth" });
  s.wait(0.5);
  s.play([rc2.scaleTo(1.12), e2.animate({ strokeWidth: 0.15 })], { duration: 0.7, ease: "smooth" });
  s.play([rc2.scaleTo(1), e2.animate({ strokeWidth: 0.09 })], { duration: 0.7, ease: "smooth" });
  s.wait(2);

  // 4. the shear again, slowly: (1-t) R + t S R
  s.play(gridTo(T).concat([labelAt(lab1, QF)]), { duration: 5, ease: "smooth" });
  s.wait(1.5);

  // 5. S applied to the green column of R
  runLine(line1, e1, PX - COLX);
  s.wait(0.7);

  // 6. S applied to the red column of R
  runLine(line2, e2, PX + COLX);

  // hold: R with coloured columns, S, and the product they produce
  s.wait(5.7);

  // ---------- handoff ----------
  s.keep(ghost);
  s.keep(plane);
  s.keep(mask);
  s.keep(panel);
  s.keep(matR);
  s.keep(rc1);
  s.keep(rc2);
  s.keep(matS);
  s.keep(frame);
  s.keep(bracket);
  s.keep(col1);
  s.keep(col2);
});
